<article class="dorm-card"><a class="card-image" href="<?= url('dorm-details.php?id=' . $d['id']) ?>"><img src="<?= e(cover_url((int)$d['id'])) ?>" alt="<?= e($d['is_demo'] ? 'Illustrative room photo for ' . $d['name'] : $d['name']) ?>" loading="lazy"><span class="photo-label"><?= $d['is_demo'] ? 'DEMO LISTING' : e($d['room_type']) ?></span></a><div class="card-body"><div class="card-meta"><span><i class="bi bi-geo-alt" aria-hidden="true"></i> <?= e($d['location']) ?>, Cebu City</span><span class="availability <?= (int)$d['available_slots'] === 0 ? 'full' : '' ?>"><?= (int)$d['available_slots'] === 0 ? 'Fully occupied' : $d['available_slots'] . ' slots left' ?></span></div><h3><a href="<?= url('dorm-details.php?id=' . $d['id']) ?>"><?= e($d['name']) ?></a></h3><p class="room-meta"><?= e($d['room_type']) ?> <span>·</span> <?= (int)$d['capacity'] ?>-person capacity</p><p class="university-line"><i class="bi bi-mortarboard" aria-hidden="true"></i> <?= e($d['university']) ?></p><div class="card-price"><div><strong><?= money($d['monthly_rent']) ?></strong><span> / month</span></div><a class="circle-link" aria-label="View <?= e($d['name']) ?>" href="<?= url('dorm-details.php?id=' . $d['id']) ?>"><i class="bi bi-arrow-up-right" aria-hidden="true"></i></a></div><div class="card-actions"><button class="text-button compare-button" type="button" data-id="<?= $d['id'] ?>" aria-pressed="false"><i class="bi bi-plus-circle" aria-hidden="true"></i> Compare</button><?php if ((current_user()['role'] ?? '') === 'student'): ?><form method="post" action="<?= url('student/favorites.php') ?>"><?= csrf() ?><input type="hidden" name="id" value="<?= $d['id'] ?>"><button class="text-button"><i class="bi bi-heart" aria-hidden="true"></i> <?= scalar('SELECT COUNT(*) FROM favorites WHERE user_id=? AND dormitory_id=?', [current_user()['id'],$d['id']]) ? 'Unsave' : 'Save' ?></button></form><?php endif; ?></div></div></article>
